        "component_id": "comp_internal_compressor",
        "name": "Internal compressor",
        "description": "Internal compressor checked during Test 9b and powered from an external 12 VDC source during testing.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_compressor_driver_board",
        "name": "Compressor-driver board",
        "description": "Board with J1, J2, and J3 connectors and diagnostic LED D5; checked for VBUS and compressor-enable voltage.",
