      },
      {
        "component_id": "comp_power_board",
        "name": "Power board",
        "description": "Board checked for VBUS and compressor-enable voltage at J9.",
        "category": "electrical"
      },
      {
        "component_id": "comp_solenoid_valve",
        "name": "Solenoid valve",
        "description": "Valve with a gas shut-off override button and gas supply hoses; moved during compressor testing.",
        "category": "pneumatic"
      },
      {
        "component_id": "comp_connectors",
        "name": "Connectors J1, J2, J3, and J9",
        "description": "Electrical connectors used to isolate the power board and check VBUS or compressor-enable voltage.",
        "category": "electrical"
      },
      {
        "component_id": "comp_twisted_pair_wires",
        "name": "J1-to-J9 twisted pair wires",
        "description": "Twisted pair wires connecting the compressor-driver board to the power board.",
        "category": "electrical"
      },
      {
        "component_id": "comp_torch",
        "name": "Torch",
        "description": "Torch whose trigger is tapped during the compressor and board checks.",
        "category": "cutting"
      },
      {
        "component_id": "comp_diagnostic_led_d5",
        "name": "Diagnostic LED D5",
        "description": "Green diagnostic LED on the compressor-driver board observed while the torch is being fired.",
        "category": "indicator"
      }
    ],
